arguments.command:
python3 -c "
with open('/workspace/task_env/free_free_block_mt_verified.rs', 'r') as f:
    content = f.read()

# Find the first occurrence of the mod free block
target = '''use crate::tokens::{Mim, BlockId, DelayState};
use crate::types::*;
use crate::layout::*;
use crate::linked_list::*;
use crate::dealloc_token::*;'''

replacement = '''use crate::tokens::{Mim, BlockId, DelayState, HeapId};
use crate::types::*;
use crate::layout::*;
use crate::linked_list::*;
use crate::dealloc_token::*;'''

# Find the one in mod free (after line 12983, which is around 12993)
idx = content.find('mod free {')
if idx == -1:
    print('mod free not found')
else:
    # Find the target AFTER 'mod free {'
    pos = content.find(target, idx)
    if pos == -1:
        print('target not found after mod free')
    else:
        content = content[:pos] + replacement + content[pos + len(target):]
        with open('/workspace/task_env/free_free_block_mt_verified.rs', 'w') as f:
            f.write(content)
        print('Done')
"

